<?php
require_once __DIR__.'/includes/module.php';
require_roles(['admin','staff']);
$page_title='Pendaftaran Pelatihan';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$training=(int)($_POST['training_id']??0);$participant=(int)($_POST['participant_id']??0);$status=$_POST['status']??'Terdaftar';$notes=trim($_POST['notes']??'');
try{$s=$pdo->prepare('INSERT INTO registrations(training_id,participant_id,status,notes) VALUES(?,?,?,?)');$s->execute([$training,$participant,$status,$notes]);flash('Pendaftaran berhasil ditambahkan.');}catch(PDOException $e){flash('Pendaftaran gagal. Periksa pilihan data atau kemungkinan peserta sudah terdaftar.');}header('Location: registrations.php');exit;}
$trainings=module_list($pdo,"SELECT id,code,title FROM trainings ORDER BY start_date DESC");$participants=module_list($pdo,"SELECT id,name,institution FROM participants ORDER BY name");
$rows=module_list($pdo,"SELECT r.*,t.code,t.title,p.name,p.institution FROM registrations r JOIN trainings t ON t.id=r.training_id JOIN participants p ON p.id=r.participant_id ORDER BY r.registered_at DESC");
require __DIR__.'/includes/header.php';show_flash();?>
<section class="panel"><div class="panel-head"><h3>Daftarkan Peserta ke Kegiatan</h3></div><?php if(!$trainings||!$participants):?><div class="notice">Tambahkan minimal satu data pelatihan dan satu peserta sebelum membuat pendaftaran.</div><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Pelatihan</label><select name="training_id" required><?php foreach($trainings as $t):?><option value="<?=$t['id']?>"><?=e($t['code'].' — '.$t['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Peserta</label><select name="participant_id" required><?php foreach($participants as $p):?><option value="<?=$p['id']?>"><?=e($p['name'].' — '.$p['institution'])?></option><?php endforeach;?></select></div><div class="field"><label>Status Pendaftaran</label><select name="status"><option>Terdaftar</option><option>Terverifikasi</option><option>Ditolak</option><option>Mengundurkan Diri</option></select></div><div class="field"><label>Catatan</label><input name="notes"></div></div><div class="form-actions"><button class="btn">Simpan Pendaftaran</button></div></form><?php endif;?></section>
<section class="panel"><div class="panel-head"><h3>Daftar Pendaftaran</h3></div><table><thead><tr><th>Peserta</th><th>Instansi</th><th>Pelatihan</th><th>Tanggal Daftar</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">Belum ada pendaftaran.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['institution'])?></td><td><?=e($r['code'].' — '.$r['title'])?></td><td><?=e($r['registered_at'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></section>
<?php require __DIR__.'/includes/footer.php';?>
